def reverseSymmetric(s, ops):
    n = len(s)
    half = n // 2
    mark = [0] * (half + 1)
    for a in ops:
        mark[min(a - 1, half)] ^= 1
    arr = list(s)
    parity = 0
    for i in range(half):
        parity ^= mark[i]
        if parity:
            arr[i], arr[n - 1 - i] = arr[n - 1 - i], arr[i]
    return ''.join(arr)
